--- 刷新顶部排期页签
function UIActionPointRankBranchDialog:RefreshToggleUpComp()
    local data = {}
    local scheduleData = self.comp:GetBranchRankScheduleData()
    for i, v in ipairs(scheduleData) do
        local cellData = {
            text = localize("第_num_期", { _num_ = v.id }),
            isLock = not v.isUnlock,
            func = function()
                if not v.isUnlock then
                    GameUtils.Toast(localize("第_num_期尚未开启", { _num_ = v.id }))
                    return
                end
                -- 请求排行榜
                self.comp:RequestBranchRank(v.id, function()
                    -- 刷新排行榜数据
                    self.rankData = self.comp:GetBranchRankData()
                    self.myRankData = self.comp:GetMyBranchRankData()
                    if IsNull(self.rankData) or #self.rankData == 0 then
                        self:SetBlankActive(true)
                    else
                        self:SetBlankActive(false)
                        self:RefreshMyselfNode()
                        self:RefreshLoopViewList(#self.rankData)
                    end
                end)
            end,
            checkFunc = function()
                return v.isUnlock
            end
        }
        table.insert(data, cellData)
    end
    local lastUnlockIndex = 1
    -- 当前解锁榜单的倒计时
    for i, cellData in fipairs(data) do
        if not cellData.isLock then
            lastUnlockIndex = i
            local countDownData = {
                textType = 2,
                isCountDown = true,
                remainTime = self.comp:GetBranchRankRemainTime(),
            }
            cellData.countDownData = countDownData
            break
        end
    end
    self.toggleUpComp:FillToggles(data, lastUnlockIndex)
end

--- 显示空白榜单
function UIActionPointRankBranchDialog:SetBlankActive(acitve)
    KTool.SetActive(self.RT_MyRankNode, not acitve)
    KTool.SetActive(self.RT_EmptyNode, acitve)
end

--- 更新显示我自己的排行信息
function UIActionPointRankBranchDialog:RefreshMyselfNode()
    local LB_myCell = GetLuaBehaviour(self.RT_MyRankNode.gameObject, RankCellLuaPath)
    LB_myCell.Env:SetComponent(self.comp)
    LB_myCell.Env:Refresh(self.myRankData)
end

--- 排行榜列表
---@param maxNum any
function UIActionPointRankBranchDialog:RefreshLoopViewList(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
        self.LoopListView:UpdateDisplayItemCount("Cell")
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function UIActionPointRankBranchDialog:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local cell = loopListView:NewListViewItem("Cell")
    local LB_cell = GetLuaBehaviour(cell.gameObject, RankCellLuaPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        LB_cell:Init()
        -- 第一页的节点播放延迟出现的动画
        if index + 1 <= loopListView.DisplayItemCount then
            CfUtils.PlayDelayShowAnimation(cell, index)
        end
    end
    local data = self.rankData[index + 1]
    local LT_cell = LB_cell.Env
    LT_cell:SetComponent(self.comp)
    LT_cell:Refresh(data)

    return cell
end

function UIActionPointRankBranchDialog:OnBranchRankEnd()
    -- 刷新分榜页签
    self:RefreshToggleUpComp()
end

return UIActionPointRankBranchDialog
